#---------------------------#
# DEBUG AREA 1W (GROUND)
@token    = debug-area-1w
@name     = DEBUG Area 1W
@level    = 30
@size     = 20 x 12
@sheet    = mmrpg-overworld-2k25
#---------------------------#
@portals[]  = spawn(17-4, hidden)
@portals[]  = goto__debug-area-1(17-4, 4-10)
@portals[]  = goto__debug-area-1w2(4-10, 14-22)
#---------------------------#
@field    = maniacal-hideaway
#---------------------------#
@encounters   = drill-mole,molier,rockscotch
#---------------------------#
@bosses[]    = upper-boss(6-4, drill-man)
@bosses[]    = lower-boss(15-10, ground-man)
#---------------------------#
@events[]    = wily-platform-left(5-2, wilypad-left, any, drop-zone, item:wily-program, activate-player-platform)
@events[]    = wily-platform-middle(6-2, wilypad-middle, any, drop-zone, item:wily-heart, activate-player-platform)
@events[]    = wily-platform-right(7-2, wilypad-right, any, drop-zone, item:wily-core, activate-player-platform)
#---------------------------#
@items[]     = wily-program-pickup(14-10, wily-program)
@items[]     = wily-heart-2(6-3, wily-heart__2)
@items[]     = copy-core-pickup-1(2-7, copy-core, x1, once)
@items[]     = copy-core-pickup-2(19-7, copy-core, x1, once)
